<script setup>
import { assetUrl } from '../assets.js';
import { ref, onMounted, onUnmounted, nextTick } from 'vue';
import { Plus, ArrowUp, ArrowUpRight, MessageSquare, ExternalLink, Square, History, X, CircleHelp, Search, ChartNoAxesCombined, Telescope, WandSparkles, BrainCircuit, Sparkles } from '@lucide/vue';
import SaturnLogo from './SaturnLogo.vue';
import { answerQuestion } from '../knowledge.js';
const props=defineProps({initialQuestion:String});
const emit=defineEmits(['open','navigate','consumed']);
const input=ref(''),busy=ref(false),messages=ref([]),chat=ref(null),sessions=ref([]),activeId=ref(null),historyOpen=ref(false),helpOpen=ref(false);
let streamTimer;
const prompts=[{title:'宇宙问答',description:'把复杂原理，变成看得懂的答案',question:'黑洞会吸走一切吗？',icon:Search,color:'blue'},{title:'行星对比',description:'看大小、看距离，感受宇宙尺度',route:'atlas',icon:ChartNoAxesCombined,color:'purple'},{title:'观星入门',description:'从月相开始，认识头顶的星空',question:'月相为什么会变化？',icon:Telescope,color:'green'},{title:'知识卡创作',description:'一个主题，整理成一张科普卡',route:'studio',icon:WandSparkles,color:'orange'},{title:'恒星故事',description:'从太阳出发，读懂星星的一生',question:'太阳为什么会发光？',icon:Sparkles,color:'pink'},{title:'天文挑战',description:'五个问题，检验你的宇宙知识力',route:'quiz',icon:BrainCircuit,color:'teal'}];
function stop(){clearInterval(streamTimer);busy.value=false}
function newChat(){stop();messages.value=[];activeId.value=null;input.value='';historyOpen.value=false}
function loadSession(session){stop();activeId.value=session.id;messages.value=session.messages;historyOpen.value=false}
function keepSession(){if(!activeId.value){activeId.value=Date.now();sessions.value.unshift({id:activeId.value,title:messages.value[0].text,messages:messages.value})}}
async function scrollChat(){await nextTick();chat.value?.scrollTo({top:chat.value.scrollHeight,behavior:'smooth'})}
async function send(text=input.value){if(busy.value||!text.trim())return;const history=[...messages.value];messages.value.push({role:'user',text:text.trim()});input.value='';busy.value=true;const response=answerQuestion(text,history);messages.value.push({role:'assistant',text:'',article:response.article});keepSession();const message=messages.value[messages.value.length-1];let i=0;streamTimer=setInterval(()=>{i+=14;message.text=response.text.slice(0,i);scrollChat();if(i>=response.text.length)stop()},22);scrollChat()}
function choose(prompt){if(prompt.route)emit('navigate',prompt.route);else send(prompt.question)}
onMounted(()=>{if(props.initialQuestion){send(props.initialQuestion);emit('consumed')}});onUnmounted(stop);
</script>
<template>
 <section class="assistant-v2"><div class="assistant-toolbar"><div><button class="icon-button" aria-label="查看对话历史" :aria-expanded="historyOpen" @click="historyOpen=!historyOpen;helpOpen=false"><History :size="20"/></button><button class="icon-button" aria-label="开始新的对话" title="新对话" @click="newChat"><MessageSquare :size="20"/><span class="new-chat-plus">+</span></button></div><span class="assistant-mode">星语 · 本地知识演示</span><button class="icon-button" aria-label="查看助手说明" :aria-expanded="helpOpen" @click="helpOpen=!helpOpen;historyOpen=false"><CircleHelp :size="21"/></button></div>
 <Transition name="popover"><aside v-if="historyOpen" class="assistant-history"><div><h2>探索记录</h2><button class="icon-button" aria-label="关闭对话历史" @click="historyOpen=false"><X :size="17"/></button></div><button class="history-new" @click="newChat"><Plus :size="16"/> 开始新的对话</button><button v-for="session in sessions" :class="['session-button',{selected:activeId===session.id}]" @click="loadSession(session)"><MessageSquare :size="15"/><span>{{session.title}}</span></button><p v-if="!sessions.length">第一个问题，会从这里出发。</p><small>记录仅保留在本次页面会话中。</small></aside></Transition>
 <Transition name="popover"><aside v-if="helpOpen" class="assistant-help"><h2>关于 AI 星语</h2><p>这是一版交互原型。当前回答来自已整理的本地科普资料，尚未连接大模型。</p><p>可以提问土星、木星、太阳、黑洞、月相、光年等话题，并沿用上一轮主题追问。</p><button class="text-button" @click="helpOpen=false">我知道了</button></aside></Transition>
 <div ref="chat" class="assistant-conversation"><div v-if="!messages.length" class="assistant-welcome"><h1><SaturnLogo :size="59"/><span>我是星语，你的宇宙探索伙伴</span></h1><div class="assistant-prompts"><button v-for="p in prompts" :key="p.title" :class="p.color" @click="choose(p)"><component :is="p.icon" :size="23" :stroke-width="1.4"/><strong>{{p.title}}</strong><span>{{p.description}}</span><small>试试：{{p.question||'去'+p.title}} <ArrowUpRight :size="13"/></small></button></div></div><h1 v-else class="sr-only">与星语的对话</h1><div class="conversation-messages"><div v-for="(message,i) in messages" :key="i" :class="['message',message.role]"><span class="message-avatar"><SaturnLogo v-if="message.role==='assistant'" :size="37"/><span v-else>我</span></span><div class="message-content"><div class="message-author">{{message.role==='assistant'?'星语 · 本地知识演示':'你'}}</div><p>{{message.text || '正在整理科普资料…'}}</p><template v-if="message.article&&(!busy||i<messages.length-1)"><a class="source-link" :href="message.article.source" target="_blank" rel="noopener noreferrer">来源：{{message.article.sourceName}} <ExternalLink :size="13"/></a><button class="related-article" @click="emit('open',message.article)"><img :src="assetUrl('/images/'+message.article.image+'.jpg')" alt=""/><span><small>继续阅读</small>{{message.article.title}}</span><ArrowUpRight :size="18"/></button><div class="message-tools"><button @click="emit('navigate','atlas')">去看行星图谱 <ArrowUpRight :size="13"/></button><button @click="emit('navigate','quiz')">试试天文挑战 <ArrowUpRight :size="13"/></button></div></template></div></div></div></div>
 <div class="assistant-compose"><form @submit.prevent="send()"><textarea v-model="input" aria-label="向星语提问" placeholder="说说你对宇宙的好奇…" rows="2" maxlength="1000" @keydown.enter.exact.prevent="send()"></textarea><div class="compose-bottom"><span><SaturnLogo :size="27"/> 让每一个为什么，都有下一步</span><button v-if="busy" type="button" class="send-button" aria-label="停止回答" @click="stop"><Square :size="17"/></button><button v-else type="submit" class="send-button" aria-label="发送问题" :disabled="!input.trim()"><ArrowUp :size="23"/></button></div></form><p>本地知识演示，尚未连接大模型 · Enter 发送 / Shift + Enter 换行</p></div></section>
</template>
